    }
    i += ann->inputs;
    for (h = 1; h < ann->hidden_layers; ++h) {
        for (j = 0; j < ann->hidden; ++j) {
            double sum = *w++ * -1.0;
            for (k = 0; k < ann->hidden; ++k) {
                sum += *w++ * i[k];
            }
            *o++ = genann_act_hidden_indirect(ann, sum);
        }
        i += ann->hidden;
    }
    double const *ret = o;
    for (j = 0; j < ann->outputs; ++j) {
        double sum = *w++ * -1.0;
        for (k = 0; k < ann->hidden; ++k) {
            sum += *w++ * i[k];
        }
        *o++ = genann_act_output_indirect(ann, sum);
    }
    ((void) sizeof ((w - ann->weight == ann->total_weights) ? 1 : 0), __extension__ ({ if (w - ann->weight == ann->total_weights) ; else __assert_fail ("w - ann->weight == ann->total_weights", "genann.c", 271, __extension__ __PRETTY_FUNCTION__); }));
    ((void) sizeof ((o - ann->output == ann->total_neurons) ? 1 : 0), __extension__ ({ if (o - ann->output == ann->total_neurons) ; else __assert_fail ("o - ann->output == ann->total_neurons", "genann.c", 272, __extension__ __PRETTY_FUNCTION__); }));
    return ret;
}

void genann_train(genann const *ann, double const *inputs, double const *desired_outputs, double learning_rate) {
    genann_run(ann, inputs);
    int h, j, k;
    {
        double const *o = ann->output + ann->inputs + ann->hidden * ann->hidden_layers;
        double *d = ann->delta + ann->hidden * ann->hidden_layers;
        double const *t = desired_outputs;
        if (genann_act_output_indirect == genann_act_linear || ann->activation_output == genann_act_linear) {
            for (j = 0; j < ann->outputs; ++j) {
                *d++ = *t++ - *o++;
            }
        } else {
            for (j = 0; j < ann->outputs; ++j) {
                *d++ = (*t - *o) * *o * (1.0 - *o);
                ++o; ++t;
            }
        }
    }
    for (h = ann->hidden_layers - 1; h >= 0; --h) {
        double const *o = ann->output + ann->inputs + (h * ann->hidden);
        double *d = ann->delta + (h * ann->hidden);
        double const * const dd = ann->delta + ((h+1) * ann->hidden);
        double const * const ww = ann->weight + ((ann->inputs+1) * ann->hidden) + ((ann->hidden+1) * ann->hidden * (h));
        for (j = 0; j < ann->hidden; ++j) {
            double delta = 0;
            for (k = 0; k < (h == ann->hidden_layers-1 ? ann->outputs : ann->hidden); ++k) {
                const double forward_delta = dd[k];
                const int windex = k * (ann->hidden + 1) + (j + 1);
                const double forward_weight = ww[windex];
                delta += forward_delta * forward_weight;
            }
            *d = *o * (1.0-*o) * delta;
            ++d; ++o;
        }
    }
    {
        double const *d = ann->delta + ann->hidden * ann->hidden_layers;
        double *w = ann->weight + (ann->hidden_layers ? ((ann->inputs+1) * ann->hidden + (ann->hidden+1) * ann->hidden * (ann->hidden_layers-1)) : (0));
        double const * const i = ann->output + (ann->hidden_layers ? (ann->inputs + (ann->hidden) * (ann->hidden_layers-1)) : 0);
        for (j = 0; j < ann->outputs; ++j) {
            *w++ += *d * learning_rate * -1.0;
            for (k = 1; k < (ann->hidden_layers ? ann->hidden : ann->inputs) + 1; ++k) {
                *w++ += *d * learning_rate * i[k-1];
            }
