        ((void) sizeof ((w - ann->weight == ann->total_weights) ? 1 : 0), __extension__ ({ if (w - ann->weight == ann->total_weights) ; else __assert_fail ("w - ann->weight == ann->total_weights", "genann.c", 362, __extension__ __PRETTY_FUNCTION__); }));
